// stellang web loader: runs app.wasm (built by `stellang --web app.st`) in the page.
//
//     <div id="app"></div>
//     <script src="app.js"></script>          (loads app.wasm from next to it; or data-wasm="url")
//
// It gives the program a console (print/println), patches the page when the app renders, routes
// DOM events to the handlers in `data-on-<event>` attributes, and runs timers and fetches.
// Generated by the stellang compiler.
(function () {
  "use strict";
  const script = document.currentScript;
  const url = (script && script.dataset.wasm) || (script ? script.src.replace(/\.js(\?.*)?$/, ".wasm") : "app.wasm");
  const dec = new TextDecoder();
  const enc = new TextEncoder();
  let ex = null;
  let depth = 0;
  let dead = false;
  const bytes = () => new Uint8Array(ex.memory.buffer);
  const view = () => new DataView(ex.memory.buffer);

  // C string at `p`
  function str(p) {
    const b = bytes();
    let e = p;
    while (b[e]) e++;
    return dec.decode(b.subarray(p, e));
  }
  // a new stellang string (only safe while stellang code is running or about to: no collection happens before)
  function put(s) {
    const b = enc.encode(s);
    const p = ex.st_new_str(b.length);
    bytes().set(b, p);
    return p;
  }

  class Exit extends Error {}

  // Every call into stellang goes through here: when the outermost one returns, nothing of stellang's
  // is on the stack, so the collector may run.
  function call(fn, ...args) {
    if (dead) return;
    depth++;
    try {
      return fn(...args);
    } catch (e) {
      dead = true;
      flush();
      if (!(e instanceof Exit) || e.code !== 0) showError(e instanceof Exit ? lastErr || `exited with ${e.code}` : String(e && e.stack || e));
      if (!(e instanceof Exit)) throw e;
    } finally {
      depth--;
      if (depth === 0 && !dead) ex.st_gc(0);
    }
  }

  function showError(msg) {
    console.error("stellang: " + msg);
    const box = document.createElement("pre");
    box.style.cssText = "position:fixed;left:12px;right:12px;bottom:12px;margin:0;padding:12px 16px;z-index:2147483647;" +
      "background:#2b0b16;color:#ffd6e0;border:1px solid #ff5d8f;border-radius:8px;font:13px/1.5 ui-monospace,monospace;white-space:pre-wrap";
    box.textContent = "stellang: " + msg;
    document.body.appendChild(box);
  }

  // ---- WASI: just enough for print and the clock ----
  const out = { 1: "", 2: "" };
  let lastErr = "";
  function flush() {
    for (const fd of [1, 2]) if (out[fd]) emit(fd, out[fd]), (out[fd] = "");
  }
  function emit(fd, line) {
    if (fd === 2) {
      lastErr = line;
      console.error(line);
    } else console.log(line);
  }
  const wasi = {
    fd_write(fd, iovs, n, written) {
      const v = view();
      let total = 0;
      for (let i = 0; i < n; i++) {
        const p = v.getUint32(iovs + i * 8, true), len = v.getUint32(iovs + i * 8 + 4, true);
        out[fd] = (out[fd] || "") + dec.decode(bytes().subarray(p, p + len));
        total += len;
      }
      let k;
      while ((k = out[fd].indexOf("\n")) >= 0) {
        emit(fd, out[fd].slice(0, k));
        out[fd] = out[fd].slice(k + 1);
      }
      v.setUint32(written, total, true);
      return 0;
    },
    fd_close: () => 0,
    fd_seek: () => 70,
    fd_fdstat_get(fd, p) {
      new Uint8Array(ex.memory.buffer, p, 24).fill(0);
      view().setUint8(p, 2); // character device
      return 0;
    },
    proc_exit(code) {
      const e = new Exit("exit");
      e.code = code;
      throw e;
    },
    environ_sizes_get(c, s) {
      view().setUint32(c, 0, true);
      view().setUint32(s, 0, true);
      return 0;
    },
    environ_get: () => 0,
    args_sizes_get(c, s) {
      view().setUint32(c, 0, true);
      view().setUint32(s, 0, true);
      return 0;
    },
    args_get: () => 0,
    clock_time_get(id, precision, p) {
      const ns = id === 0 ? BigInt(Date.now()) * 1000000n : BigInt(Math.round(performance.now() * 1e6));
      view().setBigUint64(p, ns, true);
      return 0;
    },
    random_get(p, n) {
      crypto.getRandomValues(new Uint8Array(ex.memory.buffer, p, n));
      return 0;
    },
  };
  const wasiProxy = new Proxy(wasi, { get: (t, k) => t[k] || (() => 52) }); // ENOSYS for the rest

  // ---- patching the page ----
  // Make the children of `root` look like `html`, keeping the nodes that stay (and so focus, scroll
  // and what's typed). Elements with `data-key` are matched by key, the rest by position and tag.
  function patchRoot(root, html) {
    const t = document.createElement("template");
    t.innerHTML = html;
    patchChildren(root, t.content);
  }
  const keyOf = (n) => (n.nodeType === 1 ? n.getAttribute("data-key") : null);
  const same = (a, b) => a.nodeType === b.nodeType && (a.nodeType !== 1 || (a.tagName === b.tagName && keyOf(a) === keyOf(b)));
  function patchChildren(from, to) {
    const keyed = new Map();
    for (const c of from.childNodes) {
      const k = keyOf(c);
      if (k !== null) keyed.set(k, c);
    }
    let cur = from.firstChild;
    for (const want of Array.from(to.childNodes)) {
      const k = keyOf(want);
      let have = k !== null ? keyed.get(k) : cur && keyOf(cur) === null && same(cur, want) ? cur : null;
      if (have && !same(have, want)) have = null;
      if (have) {
        if (k !== null) keyed.delete(k);
        if (have === cur) cur = cur.nextSibling;
        else from.insertBefore(have, cur);
        patchNode(have, want);
      } else {
        from.insertBefore(want, cur);
      }
    }
    while (cur) {
      const next = cur.nextSibling;
      from.removeChild(cur);
      cur = next;
    }
  }
  function patchNode(node, want) {
    if (node.nodeType !== 1) {
      if (node.nodeValue !== want.nodeValue) node.nodeValue = want.nodeValue;
      return;
    }
    for (const a of Array.from(node.attributes)) if (!want.hasAttribute(a.name)) node.removeAttribute(a.name);
    for (const a of Array.from(want.attributes)) if (node.getAttribute(a.name) !== a.value) node.setAttribute(a.name, a.value);
    const tag = node.tagName;
    if (tag === "INPUT" || tag === "SELECT" || tag === "TEXTAREA") {
      // the live state, not just the attributes
      if (node.type === "checkbox" || node.type === "radio") node.checked = want.hasAttribute("checked");
      const v = tag === "TEXTAREA" ? want.textContent : want.getAttribute("value");
      if (v !== null && node.value !== v) node.value = v;
      if (tag === "TEXTAREA") return;
    }
    patchChildren(node, want);
  }

  // ---- events: <button onclick={...}> renders data-on-click="<handler id>" ----
  const EVENTS = ["click", "dblclick", "input", "change", "submit", "keydown", "keyup", "focusin", "focusout", "pointerdown", "pointerup", "contextmenu"];
  const NAMES = { focusin: "focus", focusout: "blur" };
  function onEvent(e) {
    if (!ex) return;
    const name = NAMES[e.type] || e.type;
    for (let el = e.target; el && el.getAttribute; el = el.parentElement) {
      const id = el.getAttribute("data-on-" + name);
      if (id === null) continue;
      if (name === "submit" || (name === "click" && el.tagName === "A") || name === "contextmenu") e.preventDefault();
      const t = e.target;
      let value = "";
      if (name === "keydown" || name === "keyup") value = e.key;
      else if (name === "submit") value = new URLSearchParams(new FormData(el)).toString();
      else if (t.type === "checkbox" || t.type === "radio") value = String(t.checked);
      else if ("value" in t && typeof t.value === "string") value = t.value;
      call(() => ex.st_dispatch(+id, put(value)));
      return;
    }
  }

  // ---- what std/web.st asks of the page ----
  const timers = new Map();
  let scheduled = false;
  const env = {
    js_patch(sel, html) {
      const root = document.querySelector(str(sel));
      if (!root) throw new Error(`web.mount: no element matches ${str(sel)}`);
      patchRoot(root, str(html));
    },
    js_invalidate() {
      if (scheduled) return;
      scheduled = true;
      queueMicrotask(() => {
        scheduled = false;
        call(ex.st_render);
      });
    },
    js_timer(id, ms, repeat) {
      const fire = () => call(ex.st_timer_fire, id, repeat ? 0 : 1);
      timers.set(id, repeat ? setInterval(fire, ms) : setTimeout(() => (timers.delete(id), fire()), ms));
    },
    js_clear_timer(id) {
      clearTimeout(timers.get(id));
      clearInterval(timers.get(id));
      timers.delete(id);
    },
    js_fetch(id, method, u, body) {
      const m = str(method), b = str(body);
      const init = { method: m, headers: {} };
      if (m !== "GET" && m !== "HEAD") {
        init.body = b;
        init.headers["content-type"] = /^\s*[[{"]/.test(b) ? "application/json" : "text/plain; charset=utf-8";
      }
      fetch(str(u), init)
        .then(async (r) => [r.status, await r.text()])
        .catch((e) => [0, String(e)])
        .then(([status, text]) => call(() => ex.st_fetch_done(id, status, put(text))));
    },
    js_storage_get(k) {
      let v = null;
      try {
        v = localStorage.getItem(str(k));
      } catch (e) {}
      return put(v ?? "");
    },
    js_storage_set(k, v) {
      try {
        localStorage.setItem(str(k), str(v));
      } catch (e) {}
    },
    js_location: () => put(location.pathname + location.search + location.hash),
    js_navigate(p) {
      history.pushState(null, "", str(p));
      env.js_invalidate();
    },
    js_set_title(t) {
      document.title = str(t);
    },
    js_element_text(id) {
      const el = document.getElementById(str(id));
      return put(el ? el.textContent : "");
    },
  };

  async function start() {
    const imports = { env, wasi_snapshot_preview1: wasiProxy };
    let inst;
    try {
      inst = (await WebAssembly.instantiateStreaming(fetch(url), imports)).instance;
    } catch (e) {
      // (servers that don't send application/wasm)
      const buf = await (await fetch(url)).arrayBuffer();
      inst = (await WebAssembly.instantiate(buf, imports)).instance;
    }
    ex = inst.exports;
    for (const t of EVENTS) document.addEventListener(t, onEvent);
    addEventListener("popstate", () => env.js_invalidate());
    if (ex._initialize) ex._initialize();
    call(ex.st_start);
    window.stellang = { exports: ex, render: () => call(ex.st_render), gc: () => call(() => ex.st_gc(1)), heap: () => ex.st_heap_size() };
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start);
  else start();
})();
